  function sectionSample(rows2, y) {
    const index = Math.max(0, Math.min(rows2.length - 1, (y - 0.68) * 100));
    const lower = Math.floor(index);
    return [rows2[lower], rows2[Math.min(lower + 1, rows2.length - 1)], index - lower];
  }
  var interpolate = (a, b, t) => a + (b - a) * t;
  var unit = 5e-4;
  function buildModel(model) {
    const rows2 = sections[model];
    return {
      ...landmarks[model],
      bodyAt(y) {
        const [a, b, t] = sectionSample(rows2, y);
        return {
          rx: unit * interpolate(a[0], b[0], t),
          rz: unit * interpolate(a[1], b[1], t),
          cz: unit * interpolate(a[2], b[2], t),
          perimeter: unit * interpolate(a[3], b[3], t)
        };
      },
      // Cast from (0, bodyAt(y).cz). Zero radians is +Z and pi/2 is +X.
      radialAt(y, angle) {
        const [a, b, t] = sectionSample(rows2, y);
        const theta = Math.abs(Math.atan2(Math.sin(angle), Math.cos(angle)));
        const index = theta * 36 / Math.PI;
        const lo = Math.floor(index);
        const hi = Math.min(36, lo + 1);
        const f2 = index - lo;
        const r0 = interpolate(a[4 + lo], a[4 + hi], f2);
        const r1 = interpolate(b[4 + lo], b[4 + hi], f2);
        return unit * interpolate(r0, r1, t);
      }
    };
  }
  var avatars = { female: buildModel("female"), male: buildModel("male") };
